/// Custom commands to run before/after tool executions. See
/// https://code.claude.com/docs/en/hooks
#[derive(Serialize, Deserialize)]
#[serde(rename_all = "PascalCase")]
pub struct HooksClass {
    /// Hooks that run when settings, managed settings, or skill files change during a session.
    /// Supports matchers: user_settings, project_settings, local_settings, policy_settings,
    /// skills. Command handlers only. Exit code 2 blocks the change (except policy_settings
    /// which is audit-only). See https://code.claude.com/docs/en/hooks#configchange
    config_change: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when the working directory changes. Provides cwd (new directory) and
    /// previous_cwd. Matchers are ignored; fires on every directory change. See
    /// https://code.claude.com/docs/en/hooks#cwdchanged
    cwd_changed: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when an MCP server requests user input during a tool call. See
    /// https://code.claude.com/docs/en/hooks
    elicitation: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run after a user responds to an MCP elicitation, before the response is sent
    /// back to the server. See https://code.claude.com/docs/en/hooks
    elicitation_result: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a watched file is created, modified, or deleted. Supports filename
    /// matchers. Provides file_path and file_event_type (created, modified, deleted). See
    /// https://code.claude.com/docs/en/hooks#filechanged
    file_changed: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a CLAUDE.md or .claude/rules/*.md file is loaded into context. Fires
    /// at session start and when files are lazily loaded (e.g., nested traversal, path glob
    /// match). No decision control; used for audit logging and observability. Does not support
    /// matchers. See https://code.claude.com/docs/en/hooks#instructionsloaded
    instructions_loaded: Option<Vec<ConfigChangeElement>>,

    /// Hooks that trigger on notifications
    notification: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a tool call is denied by the auto mode classifier. Supports matchers
    /// on tool name. See https://code.claude.com/docs/en/hooks
    permission_denied: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a permission dialog appears
    permission_request: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run after the context is compacted. See https://code.claude.com/docs/en/hooks
    post_compact: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run after a full batch of parallel tool calls resolves, before the next model
    /// call. Exit code 2 blocks the agentic loop. Does not support matchers. See
    /// https://code.claude.com/docs/en/hooks
    post_tool_batch: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run after tool completion
    post_tool_use: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run after a tool fails
    post_tool_use_failure: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run before the context is compacted
    pre_compact: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run before tool calls
    pre_tool_use: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a session ends
    session_end: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a new session starts
    session_start: Option<Vec<ConfigChangeElement>>,

    /// UNDOCUMENTED. Hooks that run during repository initialization (--init, --init-only) or
    /// maintenance (--maintenance)
    setup: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when agents finish responding. Does not run on user interrupt
    stop: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a turn ends due to an API error (e.g., rate_limit,
    /// authentication_failed, billing_error, invalid_request, server_error, max_output_tokens,
    /// unknown). Matcher can scope to specific error types. Hook output and exit code are
    /// ignored. See https://code.claude.com/docs/en/hooks
    stop_failure: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a subagent is spawned
    subagent_start: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when subagents finish responding
    subagent_stop: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a task is being marked as completed. Exit code 2 prevents completion
    /// and sends feedback. Does not support matchers. See
    /// https://code.claude.com/docs/en/hooks#taskcompleted
    task_completed: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a task is being created via TaskCreate. Exit code 2 rolls back task
    /// creation. Does not support matchers. See https://code.claude.com/docs/en/hooks#taskcreated
    task_created: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when an agent team teammate is about to go idle. Exit code 2 sends
    /// feedback and keeps the teammate working. Does not support matchers. Agent teams are
    /// experimental. See https://code.claude.com/docs/en/hooks#teammateidle
    teammate_idle: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a user-typed command expands into a prompt, before it reaches Claude.
    /// Exit code 2 blocks the expansion. Supports matchers on command name. See
    /// https://code.claude.com/docs/en/hooks
    user_prompt_expansion: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a user submits a prompt
    user_prompt_submit: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a worktree is created via --worktree or isolation: "worktree" in
    /// subagents. Command handlers only, no matchers. Hook must print absolute path to created
    /// worktree on stdout; non-zero exit fails creation. See
    /// https://code.claude.com/docs/en/hooks#worktreecreate
    worktree_create: Option<Vec<ConfigChangeElement>>,

    /// Hooks that run when a worktree is being removed at session exit or when a subagent
    /// finishes. Command handlers only, no matchers. Used for cleanup tasks; cannot block
    /// removal. See https://code.claude.com/docs/en/hooks#worktreeremove
    worktree_remove: Option<Vec<ConfigChangeElement>>,
}

