/// Bash command hook
///
/// LLM prompt hook. See https://code.claude.com/docs/en/hooks#prompt-based-hooks
///
/// Agent hook with multi-turn tool access for verification. See
/// https://code.claude.com/docs/en/hooks#agent-based-hooks
///
/// HTTP webhook hook. POST JSON to a URL and receive JSON response. See
/// https://code.claude.com/docs/en/hooks#http-hook-fields
///
/// MCP tool hook. Call a tool on an already-connected MCP server. See
/// https://code.claude.com/docs/en/hooks#mcp-tool-hook-fields
#[derive(Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HookElement {
    /// Run this hook asynchronously without blocking Claude Code
    #[serde(rename = "async")]
    setting_async: Option<bool>,

    /// When true, the hook runs in the background and wakes the model when it exits with code 2.
    /// Implies async.
    async_rewake: Option<bool>,

    /// Shell command to execute
    command: Option<String>,

    /// Optional permission-rule-syntax filter (e.g., "Bash(git *)"). Evaluated only on
    /// tool-related events (PreToolUse, PostToolUse, PostToolUseFailure, PermissionRequest,
    /// PermissionDenied); on other events a hook with `if` set never runs. See
    /// https://code.claude.com/docs/en/hooks-guide#filter-hooks-with-matchers
    ///
    /// Optional permission-rule-syntax filter. Evaluated only on tool-related events
    /// (PreToolUse, PostToolUse, PostToolUseFailure, PermissionRequest, PermissionDenied); on
    /// other events a hook with `if` set never runs. See
    /// https://code.claude.com/docs/en/hooks-guide#filter-hooks-with-matchers
    #[serde(rename = "if")]
    setting_if: Option<String>,

    /// Shell interpreter for the command. "bash" uses the login shell (bash/zsh/sh);
    /// "powershell" uses pwsh. Defaults to bash.
    shell: Option<Shell>,

    /// Custom spinner message displayed while the hook runs
    status_message: Option<String>,

    /// Optional timeout in seconds
    ///
    /// Optional timeout in seconds (default: 30)
    ///
    /// Optional timeout in seconds (default: 60)
    timeout: Option<f64>,

    /// Hook type
    #[serde(rename = "type")]
    setting_type: HookType,

    /// Model to use for evaluation. Defaults to a fast model
    model: Option<String>,

    /// Prompt to evaluate with LLM. Use $ARGUMENTS placeholder for hook input JSON.
    ///
    /// Prompt describing what to verify. Use $ARGUMENTS placeholder for hook input JSON.
    prompt: Option<String>,

    /// List of environment variable names permitted for interpolation in headers. If not set, no
    /// env var interpolation is allowed.
    allowed_env_vars: Option<Vec<String>>,

    /// Custom HTTP headers (e.g., Authorization: Bearer token). Values support $VAR_NAME or
    /// ${VAR_NAME} interpolation.
    headers: Option<HashMap<String, String>>,

    /// URL to POST hook input JSON to. Endpoint must accept POST requests and return JSON.
    url: Option<String>,

    /// Arguments passed to the tool. String values support ${path} substitution from hook JSON
    /// input (e.g., ${tool_input.file_path}, ${cwd})
    input: Option<HashMap<String, Option<serde_json::Value>>>,

    /// Name of a configured MCP server (must already be connected)
    server: Option<String>,

    /// Name of the tool to call on that server
    tool: Option<String>,
}

/// Tool usage permissions configuration.
/// See https://code.claude.com/docs/en/permissions and
/// https://code.claude.com/docs/en/settings#permission-settings
