/// Filesystem access control for sandboxed commands. See
/// https://code.claude.com/docs/en/sandboxing#filesystem-isolation
#[derive(Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Filesystem {
    /// (Managed settings only) When true, only allowRead paths from managed settings are used;
    /// user, project, and local allowRead entries are ignored. denyRead still merges from all
    /// sources. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation
    allow_managed_read_paths_only: Option<bool>,

    /// Paths to re-allow reading within denyRead regions. Takes precedence over denyRead for
    /// matching paths. See
    /// https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths
    allow_read: Option<Vec<String>>,

    /// Paths where subprocesses are allowed to write. Supports prefixes: // (absolute), ~/ (home
    /// directory), / (relative to settings file), ./ or no prefix (relative path). See
    /// https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths
    allow_write: Option<Vec<String>>,

    /// Paths where subprocesses are explicitly denied read access. See
    /// https://code.claude.com/docs/en/sandboxing#filesystem-isolation
    deny_read: Option<Vec<String>>,

    /// Paths where subprocesses are explicitly denied write access. Takes precedence over
    /// allowWrite. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation
    deny_write: Option<Vec<String>>,
}

/// Configures network isolation settings for the sandboxed bash environment, including
/// domain restrictions, Unix socket access, and custom proxy configuration.
#[derive(Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Network {
    /// Allow all Unix domain socket connections. If true, this overrides allowUnixSockets. See
    /// https://code.claude.com/docs/en/sandboxing#network-isolation
    allow_all_unix_sockets: Option<bool>,

    /// Allowlist of network domains for sandboxed commands. Supports wildcard patterns like
    /// *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation
    allowed_domains: Option<Vec<String>>,

    /// Allow binding to local network addresses (e.g., localhost ports). Defaults to false if
    /// not specified. See https://code.claude.com/docs/en/sandboxing#network-isolation
    allow_local_binding: Option<bool>,

    /// macOS only. Additional XPC/Mach service names the sandbox may look up. Supports a single
    /// trailing * for prefix matching. Needed for tools that communicate via XPC such as the iOS
    /// Simulator or Playwright. See https://code.claude.com/docs/en/sandboxing#network-isolation
    allow_mach_lookup: Option<Vec<String>>,

    /// (Managed settings only) Only allowedDomains and WebFetch(domain:...) allow rules from
    /// managed settings are respected. User, project, local, and flag settings domains are
    /// ignored. Denied domains are still respected from all sources. Non-allowed domains are
    /// automatically blocked without user prompts. See
    /// https://code.claude.com/docs/en/sandboxing#network-isolation
    allow_managed_domains_only: Option<bool>,

    /// Allow Unix domain sockets for local IPC (SSH agent, Docker, etc.). Provide an array of
    /// specific paths. Defaults to blocking if not specified. See
    /// https://code.claude.com/docs/en/sandboxing#network-isolation
    allow_unix_sockets: Option<Vec<String>>,

    /// Blocklist of network domains for sandboxed commands. Blocks specific domains even when a
    /// broader allowedDomains wildcard would otherwise permit them. Supports wildcard patterns
    /// like *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation
    denied_domains: Option<Vec<String>>,

    /// HTTP proxy port to use for network filtering. If not specified, a proxy server will be
    /// started automatically. See
    /// https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration
    http_proxy_port: Option<i64>,

    /// SOCKS proxy port to use for network filtering. If not specified, a proxy server will be
    /// started automatically. See
    /// https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration
    socks_proxy_port: Option<i64>,
}

